            { id: 'servo', name: 'servo', filename: null, builtin: true, hasBlocks: true, icon: 'assets/icons/motor.svg', desc: 'Керування сервоприводами (напр. SG90) через ШІМ (стандартний machine.PWM — нічого копіювати не треба).' },
            { id: 'stepper', name: 'step / stepper', filename: 'stepper.py', builtin: false, desc: 'Крокові двигуни (напр. 28BYJ-48 + ULN2003).' },
            { id: 'pca9685', name: 'pca9685', filename: 'pca9685.py', builtin: false, desc: '16-канальний ШІМ-контролер — робот-павук, багато сервоприводів.' }
