    const LIBRARY_BY_ID = {};
    LIBRARY_CATALOG.forEach(cat => cat.libs.forEach(lib => { LIBRARY_BY_ID[lib.id] = lib; }));

    const LIB_SELECTED_KEY = 'uPy.pico.selectedLibs';
    const LIB_SOURCE_KEY_PREFIX = 'uPy.pico.libSource.';

    // =====================================================================
    // РЕАЛЬНІ БЛОКИ КОМАНД для 6 бібліотек мікроконтролера (вимога:
    // "кожна бібліотека при виборі має активувати відображення відповідної
    // групи команд — команди створи так само, як і інші в проєкті").
    // =====================================================================
    // Кожен запис LIB_MODULES[id] — дескриптор У ТОМУ Ж ФОРМАТІ, що й
    // дескриптор "модуля" в extensions.js (colour/categoryXml/
    // startBlocksXml) — тому категорії/Start-блоки цих бібліотек
